/* htmx.org 1.9.12 vendored stub - minimal for dashboard - CSP friendly */
var htmx=htmx||{};htmx.version="1.9.12";htmx.config=htmx.config||{timeout:7000};htmx.process=function(el){return el};
(function(){
function fire(name, target, detail){
  try{
    var ev=new CustomEvent(name,{bubbles:true, cancelable:true, detail:detail});
    (target||document).dispatchEvent(ev);
    document.dispatchEvent(ev);
  }catch(e){}
}
function swapContent(el, html, swap){
  if(!el) return null;
  var prev=el;
  if(swap==="outerHTML"){ el.outerHTML=html; }
  else { el.innerHTML=html; }
  var newEl = swap==="outerHTML" ? document.querySelector("#"+prev.id) || prev : el;
  return newEl;
}
function on(evt, attr, handler){
  document.addEventListener(evt,function(e){
    var a=e.target.closest("["+attr+"]");
    if(a){ handler(e,a); }
  });
}
function handleSwap(targetSel, html, swap, xhrInfo){
  var el=targetSel ? document.querySelector(targetSel) : null;
  if(!el) return;
  var detail={target:el, xhr:xhrInfo||{status:200, responseText:html, statusText:"OK"}};
  if(swap==="outerHTML"){
    var id=el.id;
    el.outerHTML=html;
    var newEl=id?document.getElementById(id):null;
    if(newEl) detail.target=newEl;
    else {
      var tmp=document.createElement("div"); tmp.innerHTML=html;
      if(tmp.firstElementChild) detail.target=tmp.firstElementChild;
    }
  } else {
    el.innerHTML=html;
  }
  fire("htmx:afterSwap", detail.target, detail);
  setTimeout(function(){ fire("htmx:afterSettle", detail.target, detail); fire("htmx:load", detail.target, {}); },0);
  return detail.target;
}
on("click","hx-get",function(e, t){
  var url=t.getAttribute("hx-get"); if(!url) return;
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  var indicator=t.getAttribute("hx-indicator");
  if(indicator){ var ind=document.querySelector(indicator); if(ind) ind.classList.add("htmx-request"); }
  fetch(url,{headers:{"HX-Request":"true"}}).then(function(r){
    return r.text().then(function(c){
      var xhr={status:r.status, statusText:r.statusText, responseText:c};
      if(!r.ok){
        fire("htmx:responseError", document.body, {target:tar?document.querySelector(tar):t, xhr:xhr});
        if(tar && c) handleSwap(tar,c,sw,xhr);
        return;
      }
      handleSwap(tar,c,sw,xhr);
    });
  }).catch(function(err){
    fire("htmx:sendError", document.body, {target:tar?document.querySelector(tar):t, xhr:{status:0, responseText:""}});
  }).finally(function(){
    if(indicator){ var ind2=document.querySelector(indicator); if(ind2) ind2.classList.remove("htmx-request"); }
  });
  if(t.tagName!=="A") e.preventDefault();
});
on("submit","hx-post",function(e,t){
  e.preventDefault();
  var url=t.getAttribute("hx-post"); var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  var data=new FormData(t);
  fetch(url,{method:"POST",body:data,headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    var xhr={status:r.status, responseText:c, statusText:r.statusText};
    if(!r.ok){ fire("htmx:responseError", document.body, {target:tar?document.querySelector(tar):t, xhr:xhr}); }
    handleSwap(tar,c,sw,xhr);
  });}).catch(function(){ fire("htmx:sendError", document.body, {target:tar?document.querySelector(tar):t, xhr:{status:0}}); });
});
on("click","hx-delete",function(e,t){
  if(t.getAttribute("hx-confirm") && !confirm(t.getAttribute("hx-confirm"))) return;
  var url=t.getAttribute("hx-delete"); var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"DELETE",headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    if(tar==="closest tr"){ var tr=t.closest("tr"); if(tr) tr.remove(); return; }
    if(c && tar) handleSwap(tar,c,sw,{status:r.status, responseText:c});
    else if(tar==="closest tr" && !c){ var tr2=t.closest("tr"); if(tr2) tr2.remove(); }
  });});
});
on("click","hx-patch",function(e,t){
  var url=t.getAttribute("hx-patch"); var vals=t.getAttribute("hx-vals"); var hdr=t.getAttribute("hx-headers");
  var body=null; try{ body=vals?JSON.parse(vals):{}; }catch(_){ body={}; }
  var headers={"HX-Request":"true"}; if(hdr) try{ Object.assign(headers, JSON.parse(hdr)); }catch(_){}
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json"},headers),body:JSON.stringify(body)}).then(function(r){return r.text().then(function(c){
    var xhr={status:r.status, responseText:c};
    if(tar) handleSwap(tar,c,sw,xhr);
  });});
});
on("click","hx-post",function(e,t){
  if(t.tagName==="FORM") return;
  var url=t.getAttribute("hx-post"); if(!url) return;
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"POST",headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    handleSwap(tar,c,sw,{status:r.status, responseText:c});
  });});
});
function doLoad(){
  document.querySelectorAll("[hx-trigger]").forEach(function(el){
    var trig=el.getAttribute("hx-trigger")||""; if(trig.indexOf("load")===-1) return;
    var url=el.getAttribute("hx-get"); if(!url) return;
    var tar=el.getAttribute("hx-target"); var sw=el.getAttribute("hx-swap")||"innerHTML";
    fetch(url,{headers:{"HX-Request":"true"}}).then(function(r){return r.text()}).then(function(html){
      handleSwap(tar,html,sw,{status:200, responseText:html});
    });
  });
  fire("htmx:load", document.body, {});
}
if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",doLoad); else doLoad();
})();
